const { ShopifyClientError, normalizeClientError } = require('../errors');
const { requireWithFallback } = require('../require-package');

const {
  getAllFiles,
  createFile,
  updateFile,
  deleteFile,
  extractFilenameFromUrl,
  normalizeFilename,
  findMatchingFile,
  getFileUrl
} = requireWithFallback(
  require,
  '../../../../../lib/objects/media',
  '../../../../cli/lib/objects/media'
);

function wrap(operation, fn) {
  return async (...args) => {
    try {
      return await fn(...args);
    } catch (error) {
      throw normalizeClientError(error, `${operation} failed`);
    }
  };
}

function createMediaClient({ store }) {
  if (!store) {
    throw new ShopifyClientError('Media client requires a bound store', {
      code: 'MISSING_STORE'
    });
  }

  return {
    listAll: wrap('Media list', () => getAllFiles(store)),
    create: wrap('Media create', (fileInput) => createFile(store, fileInput)),
    update: wrap('Media update', (fileInput) => updateFile(store, fileInput)),
    delete: wrap('Media delete', (fileId) => deleteFile(store, fileId)),
    extractFilenameFromUrl,
    normalizeFilename,
    findMatchingFile,
    getFileUrl
  };
}

module.exports = {
  createMediaClient
};
